package com.dreamseekers;
import com.solegendary.reignofnether.unit.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.gametest.*;
@GameTestHolder(DreamseekersMod.MOD_ID) @PrefixGameTestTemplate(false)
public final class ShadowGolemMovementGameTests {
    static final String BATCH="dreamseekers_shadow_golem_movement";
    @AfterBatch(batch=BATCH) public static void cleanup(ServerLevel l){ShadowGolemFixture.cleanup(l);}
    @GameTest(template="golem_unit_arena",batch=BATCH,timeoutTicks=720)
    public static void solidBarrierRequiresGroundDetour(GameTestHelper h){var f=new ShadowGolemFixture(h);var u=f.unit("Barrier",5,10);var goal=f.pos(24,0,10);for(int z=2;z<=20;z++)for(int y=1;y<=5;y++)f.set(14,y,z,Blocks.STONE);boolean[] detour={false};var t=new ShadowGolemFixture.Timeline(h);t.at(0,()->f.order(u,UnitAction.MOVE,goal));for(int i=1;i<=580;i++)t.at(i,()->{h.assertTrue(h.getLevel().noCollision(u)&&!u.isNoGravity()&&!u.noPhysics&&u.getY()<f.pos(0,2,0).getY(),"solid real ground body never flies through wall");if(u.getZ()<f.pos(0,0,2).getZ()||u.getZ()>f.pos(0,0,21).getZ())detour[0]=true;});t.at(590,()->h.assertTrue(detour[0]&&f.near(u,goal),"real detour reaches ordered ground point: "+f.state(u)));t.start(u,()->f.ready(u));}
    @GameTest(template="golem_unit_arena",batch=BATCH,timeoutTicks=750)
    public static void bodyNeedsBothWidthAndFourBlockHeadroom(GameTestHelper h){var f=new ShadowGolemFixture(h);var u=f.unit("Body",5,10);var goal=f.pos(23,0,10);for(int z=0;z<32;z++)for(int y=1;y<12;y++)if(z!=10||y>3)f.set(14,y,z,Blocks.STONE);var t=new ShadowGolemFixture.Timeline(h);t.at(0,()->f.order(u,UnitAction.MOVE,goal));for(int i=1;i<=120;i++)t.at(i,()->h.assertTrue(u.getX()<f.pos(14,0,0).getX()&&h.getLevel().noCollision(u),"1-wide 3-high hole cannot fit 2.2x3.5 body"));t.at(130,()->{for(int z=9;z<=11;z++)for(int y=1;y<=3;y++)f.set(14,y,z,Blocks.AIR);});for(int i=131;i<=230;i++)t.at(i,()->h.assertTrue(u.getX()<f.pos(14,0,0).getX()&&h.getLevel().noCollision(u),"3-wide hole still too low"));t.at(240,()->{for(int z=9;z<=11;z++)for(int y=4;y<=4;y++)f.set(14,y,z,Blocks.AIR);});t.at(640,()->h.assertTrue(f.near(u,goal)&&Math.abs(u.getBbWidth()-2.2)<.001&&Math.abs(u.getBbHeight()-3.5)<.001,"same retained order crosses genuine 3x4 opening: "+f.state(u)));t.start(u,()->f.ready(u));}
    @GameTest(template="golem_unit_arena",batch=BATCH,timeoutTicks=1080)
    public static void shiftHoldStopAndSameTickAbaKeepFinalIntent(GameTestHelper h){var f=new ShadowGolemFixture(h);var u=f.unit("Queue",5,5);var a=f.pos(20,0,5);var b=f.pos(20,0,23);boolean[] first={false};Vec3[] stopped={null};var t=new ShadowGolemFixture.Timeline(h);t.at(0,()->{f.order(u,UnitAction.MOVE,a);UnitServerEvents.addActionItem(u.getOwnerName(),UnitAction.MOVE,-1,new int[]{u.getId()},b,BlockPos.ZERO,true);});for(int i=1;i<=458;i++)t.at(i,()->{if(u.distanceToSqr(a.getCenter())<4)first[0]=true;h.assertTrue(h.getLevel().noCollision(u),"real queued collision");});t.at(470,()->{h.assertTrue(first[0]&&f.near(u,b),"both Shift points actually visited: "+f.state(u));f.order(u,UnitAction.MOVE,a);f.order(u,UnitAction.HOLD,BlockPos.ZERO);});t.at(494,()->{h.assertTrue(u.getHoldPosition()&&u.getMoveGoal().getMoveTarget()==null,"HOLD cancels move");stopped[0]=u.position();});t.at(540,()->{h.assertTrue(u.position().distanceToSqr(stopped[0])<.1,"held stationary");f.order(u,UnitAction.MOVE,a);f.order(u,UnitAction.STOP,BlockPos.ZERO);});t.at(564,()->{h.assertTrue(!u.getHoldPosition()&&u.getMoveGoal().getMoveTarget()==null,"STOP cancels path and releases hold");f.order(u,UnitAction.MOVE,a);f.order(u,UnitAction.MOVE,b);f.order(u,UnitAction.MOVE,a);});t.at(857,()->h.assertTrue(f.near(u,a),"A-B-A last order reaches A: "+f.state(u)));for(int i=859;i<=893;i++)t.at(i,()->h.assertTrue(f.near(u,a),"no delayed old path revival"));t.start(u,()->f.ready(u));}
    @GameTest(template="golem_unit_arena",batch=BATCH,timeoutTicks=610)
    public static void attackMoveWithoutEnemiesThenShiftUsesGroundController(GameTestHelper h){var f=new ShadowGolemFixture(h);var u=f.unit("AttackMove",5,5);var a=f.pos(19,0,17);var b=f.pos(6,0,24);boolean[] visited={false};var t=new ShadowGolemFixture.Timeline(h);t.at(0,()->{f.order(u,UnitAction.ATTACK_MOVE,a);UnitServerEvents.addActionItem(u.getOwnerName(),UnitAction.MOVE,-1,new int[]{u.getId()},b,BlockPos.ZERO,true);});for(int i=1;i<=494;i++)t.at(i,()->{if(u.distanceToSqr(a.getCenter())<4)visited[0]=true;});t.at(505,()->h.assertTrue(visited[0]&&f.near(u,b)&&u.getAttackMoveTarget()==null,"actual unopposed attack-move then queued move: "+f.state(u)));t.start(u,()->f.ready(u));}
}
